import{G as e,b as t,c as r,ae as o}from"./chunks/framework.l_MR1ur9.js";const v=JSON.parse('{"title":"面试问题(一)","description":"","frontmatter":{"title":"面试问题(一)","date":"2024-03-12 11:13:22","author":"花木凋零成兰","tags":["面试"],"categories":["面试"]},"headers":[],"relativePath":"Interview/面试问题-一.md","filePath":"Interview/面试问题-一.md","lastUpdated":1791630580000}'),l={name:"Interview/面试问题-一.md"};function i(d,a,n,h,c,p){return t(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1710242002000"},[...a[0]||(a[0]=[o('<h1 id="面试问题-一" tabindex="-1">面试问题(一) <a class="header-anchor" href="#面试问题-一" aria-label="Permalink to &quot;面试问题(一)&quot;">​</a></h1><h2 id="自我介绍" tabindex="-1">自我介绍 <a class="header-anchor" href="#自我介绍" aria-label="Permalink to &quot;自我介绍&quot;">​</a></h2><p>控制时间、与岗位相关的经历、为什么你能够胜任、为什么要应聘 满足岗位的优势和亮点 表现对岗位的理解和职业规划</p><h2 id="jdbc连接数据库怎么实现的-用的哪些类" tabindex="-1">JDBC连接数据库怎么实现的(用的哪些类) <a class="header-anchor" href="#jdbc连接数据库怎么实现的-用的哪些类" aria-label="Permalink to &quot;JDBC连接数据库怎么实现的(用的哪些类)&quot;">​</a></h2><ol><li><code>DataSource</code>数据源类</li><li><code>Connection</code>数据库连接类</li><li><code>String</code>类，用于写动态<code>sql</code>语句</li><li><code>PreparedStatement</code>，接收连接类，并用于设置动态<code>sql</code>的参数</li><li><code>ResultSet</code>，查询数据时，用于接收查询结果</li></ol><p><a href="https://blog.csdn.net/qq_62958114/article/details/128268400" target="_blank" rel="noreferrer">参考文章</a></p><h2 id="对java语言怎么理解的" tabindex="-1">对Java语言怎么理解的 <a class="header-anchor" href="#对java语言怎么理解的" aria-label="Permalink to &quot;对Java语言怎么理解的&quot;">​</a></h2><p>Java是一种面向对象的编程语言，具有跨平台、安全性高、稳定性好等特点。与C++等编程语言相比，Java拥有更简洁的语法和更好的跨平台性，而且Java的自动内存管理和垃圾回收机制减轻了程序员的负担，降低了程序出错的可能性。</p><p>Java虚拟机（JVM）是Java的核心，它负责将Java源代码编译成字节码，并在不同平台上运行。JVM通过将字节码翻译成本地机器码，实现了Java的跨平台特性。而Java运行时环境（JRE）则包含JVM和运行Java程序所需的核心类库，提供了Java程序运行的基本环境.</p><p><a href="https://zhuanlan.zhihu.com/p/686947239" target="_blank" rel="noreferrer">参考文章1</a><a href="https://www.zhihu.com/question/626179755" target="_blank" rel="noreferrer">参考文章2</a></p><h2 id="jvm怎么运行的" tabindex="-1">jvm怎么运行的 <a class="header-anchor" href="#jvm怎么运行的" aria-label="Permalink to &quot;jvm怎么运行的&quot;">​</a></h2><p>首先根据系统版本，加载jvm.cfg配置文件，然后根据配置文件找到jvm.dll文件，并初始化jvm，获取JNI接口，然后找到Java程序字节码文件的main方法并运行。</p><p>JNI接口： 是Java本地接口，通过JNI接口才能装载class文件，常用于和操作系统、硬件交互。</p><p><a href="https://blog.csdn.net/weixin_43943548/article/details/90721796" target="_blank" rel="noreferrer">参考文章</a></p><h2 id="你是怎么学习java的" tabindex="-1">你是怎么学习Java的 <a class="header-anchor" href="#你是怎么学习java的" aria-label="Permalink to &quot;你是怎么学习Java的&quot;">​</a></h2><h2 id="你觉得作为一名java程序员需要具备哪些素质" tabindex="-1">你觉得作为一名Java程序员需要具备哪些素质 <a class="header-anchor" href="#你觉得作为一名java程序员需要具备哪些素质" aria-label="Permalink to &quot;你觉得作为一名Java程序员需要具备哪些素质&quot;">​</a></h2><h2 id="你是如何理解面向对象的" tabindex="-1">你是如何理解面向对象的 <a class="header-anchor" href="#你是如何理解面向对象的" aria-label="Permalink to &quot;你是如何理解面向对象的&quot;">​</a></h2><p>1、面向过程与面向对象对比理解；</p><p>2、举生活案例</p><p>3、讲述面向对象与面向过程的特点</p><ul><li>面向过程；注重于系统的一系列过程或函数，通过调用这些过程来完成任务；强调算法和流程，修改过程的一个地方，可能会影响到其他调用改过程的地方；一般是简单的、线性的任务。</li><li>面向对象；更注重事情的参与者，先抽象出具有状态、行为的对象，然后通过对象执行方法的方式解决问题，强调封装、继承和多态；更易于维护和拓展，因为修改一个对象不会影响到其他对象；适合复杂的系统</li></ul><p>4、介绍面向对象的三个特性；封装、继承、多态</p><p>（1）、封装</p><p>就是通过访问修饰符<code>private</code>将对象内部的字段、属性隐藏起来，并通过定义公共接口来对其进行访问，从而提高代码安全性，隐藏对象的内部细节</p><p>（2）、继承</p><p>在Java中，子类通过<code>extend</code>关键字继承父类，然后子类可以重用父类的代码，并通过添加新的方法或重写已有的方法来扩展或改进功能；提高了代码的重用性和可扩展性</p><p>（3）、多态</p><p>多态是指相同的操作或方法可以在不同的对象上产生不同的行为，通过方法的重写和重载实现，多态允许一致的式处理不同类型的对象，提高了代码的灵活性。</p><p><a href="https://blog.csdn.net/qfguan/article/details/121226260" target="_blank" rel="noreferrer">参考文章</a></p><h2 id="你在学校有没有参加过社团和学生会" tabindex="-1">你在学校有没有参加过社团和学生会 <a class="header-anchor" href="#你在学校有没有参加过社团和学生会" aria-label="Permalink to &quot;你在学校有没有参加过社团和学生会&quot;">​</a></h2><p>有</p><h2 id="你为什么选择java这个行业" tabindex="-1">你为什么选择Java这个行业 <a class="header-anchor" href="#你为什么选择java这个行业" aria-label="Permalink to &quot;你为什么选择Java这个行业&quot;">​</a></h2><p>个人爱好 看好前景</p>',33)])])}const u=e(l,[["render",i]]);export{v as __pageData,u as default};
